import { readFile, writeFile } from 'node:fs/promises';

const schemaUrl = new URL('../src/font-baker/schemas/extensions/glTF.PMNDRS_font.schema.json', import.meta.url);
const outputUrl = new URL('../src/generated/font-artifact-schema.ts', import.meta.url);
const check = process.argv.includes('--check');
const schema = JSON.parse(await readFile(schemaUrl, 'utf8'));
const source = `// Generated by scripts/generate-font-schema-types.mjs from
// src/font-baker/schemas/extensions/glTF.PMNDRS_font.schema.json. Do not edit by hand.

export type PmndrsFontExtension = ${typescriptType(schema, 0)};
`;

if (check) {
  const existing = await readFile(outputUrl, 'utf8').catch(() => undefined);
  if (existing !== source) {
    console.error('generated PMNDRS_font schema types are stale; run scripts/generate-font-schema-types.mjs');
    process.exitCode = 1;
  }
} else {
  await writeFile(outputUrl, source);
}

function typescriptType(value, depth) {
  if (Array.isArray(value.oneOf)) {
    return value.oneOf.map((entry) => typescriptType(entry, depth)).join(' | ');
  }
  if (Array.isArray(value.enum)) return value.enum.map((entry) => JSON.stringify(entry)).join(' | ');
  if (value.type === 'array') return `readonly (${typescriptType(value.items ?? {}, depth)})[]`;
  if (value.type === 'object' || value.properties !== undefined) {
    const required = new Set(value.required ?? []);
    const indentation = '  '.repeat(depth);
    const childIndentation = '  '.repeat(depth + 1);
    const properties = Object.entries(value.properties ?? {}).map(
      ([name, property]) =>
        `${childIndentation}readonly ${propertyName(name)}${required.has(name) ? '' : '?'}: ${typescriptType(property, depth + 1)};`,
    );
    return properties.length === 0
      ? 'Readonly<Record<string, unknown>>'
      : `{\n${properties.join('\n')}\n${indentation}}`;
  }
  if (value.type === 'integer' || value.type === 'number') return 'number';
  if (value.type === 'string') return 'string';
  if (value.type === 'boolean') return 'boolean';
  if (value.type === 'null') return 'null';
  return 'unknown';
}

function propertyName(value) {
  return /^[A-Za-z_$][\w$]*$/.test(value) ? value : JSON.stringify(value);
}
